        "surface_brushed": "Бршированная поверхность - это то, что лучше всего подходит для металла, и только иногда работает на дереве или обработанном пластмассе.",
        "surface_rough": "Опасные тактильные поверхности обычно лучше работают на дереве, камне, глине, бумаге или натуральных материалах.",
        "surface_porous": "Поровые поверхности обычно не подходят для использования в стекле или чистых металлических материалах.",
        "surface_grainy": "Плохое зерно обычно лучше подходит для использования в деревянных, глиняных, каменных, бумажных или органических материалах.",
        "surface_fibrous": "В натуральных материалах, таких как ткань, бумага, древесина или органические материалы, используется более натуральная влажная текстура.",
        "surface_woven": "В основном тканящая текстура подходит для производства тканей или текстильных материалов.",
