        "imperfection_grain": "Плохое зерно обычно лучше подходит для использования в древесине, глине, камнях, бумаге или пористом органическом материале.",
        "imperfection_brush_marks": "На крашенных, ручной работы, бумаге, дереве, глине или керамической поверхности, как правило, больше смысла имеют отпечатки кистей.",
        "imperfection_paint_splatter": "Обычно красочные шпаттеры лучше работают на красках, бумаге, холсте, дереве, пластике, смоле или игрушечных материалах.",
        "imperfection_scratches": "Обычно на твердых материалах, таких как металл, пластик, стекло, дерево или кожа, царапины прозрачнее.",
        "imperfection_cracks": "Расколы обычно встречаются в глине, керамике, камнях, дереве, краске, стекле или хрупких материалах.",
