        "imperfection_roughness": "Обычно грубая неравномерная текстура менее подходит для стекла, кристалла, шелка, ветру или очень гладких материалов.",
        "imperfection_fading": "Обычно цвет, испачкавший, лучше подойдет для ткани, бумаги, кожа, дерева, пластика или крашенных материалов.",
